<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import type { ColDef } from 'ag-grid-community'
import { ElMessage, ElMessageBox } from 'element-plus'
import AppDataGrid from '@/components/AppDataGrid.vue'
import { deleteDNSProvider, getDNSProvider, listDNSProviders, saveDNSProvider, testDNSProvider, type SSLDNSProvider } from '@/api/ssl-cert'
import { useAuthStore } from '@/stores/auth'

type DNSCredentials = { access_key_id:string; access_key_secret:string; security_token:string; secret_id:string; secret_key:string; session_token:string; api_token:string; zone_token:string; cloudflare_email:string; api_key:string; secret_access_key:string; region:string }
const emptyCredentials = ():DNSCredentials => ({ access_key_id:'', access_key_secret:'', security_token:'', secret_id:'', secret_key:'', session_token:'', api_token:'', zone_token:'', cloudflare_email:'', api_key:'', secret_access_key:'', region:'cn-hangzhou' })
const auth=useAuthStore(),rows=ref<SSLDNSProvider[]>([]),keyword=ref(''),provider=ref(''),page=ref(1),pageSize=ref(20),total=ref(0),loading=ref(false),dialog=ref(false)
const empty=()=>({id:undefined as number|undefined,name:'',provider:'alidns',config:'',email:'',phone:'',enabled:true})
const form=reactive(empty()),credentials=reactive<DNSCredentials>(emptyCredentials())
async function load(){loading.value=true;try{const{data}=await listDNSProviders({keyword:keyword.value,provider:provider.value,page:page.value,limit:pageSize.value});rows.value=data.data.list;total.value=data.data.total}finally{loading.value=false}}
async function open(row?:SSLDNSProvider){Object.assign(form,empty());Object.assign(credentials,emptyCredentials());if(row){const{data}=await getDNSProvider(row.id);Object.assign(form,data.data);try{const value=JSON.parse(data.data.config||'{}') as Record<string,string>;Object.assign(credentials,value,{cloudflare_email:value.email||''})}catch{ElMessage.warning('已保存的 DNS 凭据格式无效')}}dialog.value=true}
function configPayload(){switch(form.provider){case'alidns':return{access_key_id:credentials.access_key_id,access_key_secret:credentials.access_key_secret,security_token:credentials.security_token,region:credentials.region};case'tencentcloud':return{secret_id:credentials.secret_id,secret_key:credentials.secret_key,session_token:credentials.session_token,region:credentials.region};case'cloudflare':return{api_token:credentials.api_token,zone_token:credentials.zone_token,email:credentials.cloudflare_email,api_key:credentials.api_key};case'huaweicloud':return{access_key_id:credentials.access_key_id,secret_access_key:credentials.secret_access_key,region:credentials.region};default:return{}}}
async function save(){if(!form.name.trim())return ElMessage.warning('请输入配置名称');form.config=JSON.stringify(configPayload());await saveDNSProvider(form);dialog.value=false;ElMessage.success('保存成功');await load()}
async function remove(row:SSLDNSProvider,confirm=true){if(confirm)await ElMessageBox.confirm(`确认删除“${row.name}”吗？`,'删除确认',{type:'warning'});await deleteDNSProvider(row.id)}
async function bulkDelete(items:unknown[]){await ElMessageBox.confirm(`确认删除选中的 ${items.length} 项吗？`,'批量删除',{type:'warning'});for(const row of items as SSLDNSProvider[])await remove(row,false);await load()}
async function test(row:SSLDNSProvider){await testDNSProvider(row.id);ElMessage.success('配置验证通过');await load()}
function changeProvider(value:string){Object.assign(credentials,emptyCredentials());credentials.region=value==='tencentcloud'?'ap-guangzhou':value==='huaweicloud'?'cn-north-4':'cn-hangzhou'}
function actions(p:{data:SSLDNSProvider}){const w=document.createElement('div');w.className='ssl-grid-actions';const add=(t:string,kind:string,f:()=>void)=>{const b=document.createElement('button');b.type='button';b.textContent=t;b.className=`grid-action compact ${kind}`;b.addEventListener('click',event=>{event.stopPropagation();f()});w.append(b)};if(auth.hasPermission('POST /api/v1/ssl-cert/dns-providers/test'))add('测试','permission',()=>void test(p.data));if(auth.hasPermission('POST /api/v1/ssl-cert/dns-providers/save'))add('编辑','edit',()=>void open(p.data));if(auth.hasPermission('POST /api/v1/ssl-cert/dns-providers/delete'))add('删除','delete',()=>void remove(p.data).then(load));return w}
const columns=computed<ColDef[]>(()=>[{headerName:'序号',width:64,valueGetter:p=>(page.value-1)*pageSize.value+(p.node?.rowIndex||0)+1},{field:'name',headerName:'配置名称',minWidth:150},{field:'provider',headerName:'DNS 服务商',minWidth:120},{field:'email',headerName:'联系邮箱',minWidth:160,valueFormatter:p=>p.value||'-'},{field:'enabled',headerName:'状态',width:85,valueFormatter:p=>p.value?'启用':'停用'},{field:'last_test_ok',headerName:'最近测试',width:100,valueFormatter:p=>p.data.last_test_at?(p.value?'通过':'失败'):'未测试'},{headerName:'操作',pinned:'right',width:150,minWidth:150,maxWidth:150,cellClass:'ssl-operation-cell',cellRenderer:actions}])
watch([keyword,provider],()=>{page.value=1;void load()});onMounted(load)
</script>
<template><section class="ssl-page"><header><h2>DNS 配置</h2><p>维护 ACME DNS 验证所需的服务商凭据。</p></header><div class="toolbar"><div class="filters"><el-input v-model="keyword" placeholder="搜索配置名称" clearable/><el-select v-model="provider" placeholder="选择 DNS 服务商" clearable><el-option label="AliDNS" value="alidns"/><el-option label="Tencent Cloud DNS" value="tencentcloud"/><el-option label="Cloudflare" value="cloudflare"/><el-option label="Huawei Cloud DNS" value="huaweicloud"/></el-select></div><el-button v-permission="'POST /api/v1/ssl-cert/dns-providers/save'" type="primary" @click="open()">新增 DNS 配置</el-button></div><AppDataGrid v-loading="loading" class="grid" :row-data="rows" :column-defs="columns" pagination server-pagination :total="total" :current-page="page" :page-size="pageSize" :bulk-delete="auth.hasPermission('POST /api/v1/ssl-cert/dns-providers/delete')?bulkDelete:undefined" @page-change="v=>{page=v;void load()}" @page-size-change="v=>{pageSize=v;page=1;void load()}"/><el-dialog v-model="dialog" :title="form.id?'编辑 DNS 配置':'新增 DNS 配置'" width="620px"><el-form label-width="105px"><el-form-item label="配置名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="服务商" required><el-select v-model="form.provider" style="width:100%" @change="changeProvider"><el-option label="AliDNS" value="alidns"/><el-option label="Tencent Cloud DNS" value="tencentcloud"/><el-option label="Cloudflare" value="cloudflare"/><el-option label="Huawei Cloud DNS" value="huaweicloud"/></el-select></el-form-item>
<template v-if="form.provider==='alidns'"><el-form-item label="AccessKey ID" required><el-input v-model="credentials.access_key_id"/></el-form-item><el-form-item label="AccessKey Secret" required><el-input v-model="credentials.access_key_secret" type="password" show-password :placeholder="form.id?'留空表示不修改':'请输入 AccessKey Secret'"/></el-form-item><el-form-item label="Security Token"><el-input v-model="credentials.security_token" type="password" show-password :placeholder="form.id?'留空表示不修改':'可选'"/></el-form-item><el-form-item label="地域"><el-input v-model="credentials.region"/></el-form-item></template>
<template v-else-if="form.provider==='tencentcloud'"><el-form-item label="Secret ID" required><el-input v-model="credentials.secret_id"/></el-form-item><el-form-item label="Secret Key" required><el-input v-model="credentials.secret_key" type="password" show-password :placeholder="form.id?'留空表示不修改':'请输入 Secret Key'"/></el-form-item><el-form-item label="Session Token"><el-input v-model="credentials.session_token" type="password" show-password :placeholder="form.id?'留空表示不修改':'可选'"/></el-form-item><el-form-item label="地域"><el-input v-model="credentials.region"/></el-form-item></template>
<template v-else-if="form.provider==='cloudflare'"><el-form-item label="API Token"><el-input v-model="credentials.api_token" type="password" show-password :placeholder="form.id?'留空表示不修改':'推荐使用 API Token'"/></el-form-item><el-form-item label="Zone Token"><el-input v-model="credentials.zone_token" type="password" show-password :placeholder="form.id?'留空表示不修改':'可选'"/></el-form-item><el-form-item label="账户邮箱"><el-input v-model="credentials.cloudflare_email"/></el-form-item><el-form-item label="Global API Key"><el-input v-model="credentials.api_key" type="password" show-password :placeholder="form.id?'留空表示不修改':'使用账户邮箱时填写'"/></el-form-item></template>
<template v-else-if="form.provider==='huaweicloud'"><el-form-item label="AccessKey ID" required><el-input v-model="credentials.access_key_id"/></el-form-item><el-form-item label="Secret AccessKey" required><el-input v-model="credentials.secret_access_key" type="password" show-password :placeholder="form.id?'留空表示不修改':'请输入 Secret AccessKey'"/></el-form-item><el-form-item label="地域"><el-input v-model="credentials.region"/></el-form-item></template>
<div class="form-row"><el-form-item label="联系邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.phone"/></el-form-item></div><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.ssl-page{height:100%;display:flex;flex-direction:column;gap:8px;min-width:0;padding:0 4px;font-size:11px}header h2{margin:0;font-size:20px}header p{margin:3px 0 0;color:var(--text-soft)}.toolbar{display:flex;justify-content:space-between;gap:8px}.filters{display:flex;gap:6px}.filters .el-input{width:150px}.filters .el-select{width:150px}.grid{flex:1;min-height:0}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}:deep(.ssl-actions){height:100%;display:flex;align-items:center;gap:5px}:deep(.ssl-actions button){height:26px;border-radius:8px;padding:3px 8px;background:#fff;cursor:pointer}:deep(.ssl-edit){border:1px solid var(--primary);color:var(--primary)}:deep(.ssl-test){border:1px solid #7bcf91;color:#27ae60}:deep(.ssl-delete){border:1px solid #f3b4b4;color:var(--danger)}</style>
